corrected_code:
import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { db } from '@/db';

export async function PATCH(
  req: NextRequest,
  { params }: { params: { domainId: string } }
) {
  const session = await getServerSession(authOptions);
  if (!session?.user) {
    return NextResponse.json({ message: 'Unauthorized' }, { status: 401 });
  }

  const domain = await db.domain.findFirst({
    where: { id: params.domainId, ownerId: session.user.id }
  });
  if (!domain) {
    return NextResponse.json({ message: 'Domain not found or access denied' }, { status: 403 });
  }

  const { nameservers, targetIp } = await req.json();
  const updatedDomain = await db.domain.update({
    where: { id: params.domainId },
    data: { nameservers, targetIp, status: 'PENDING_VERIFICATION' }
  });

  return NextResponse.json({ success: true, domain: updatedDomain });
}
